SELECT 
FROM quarterly_snapshot
WHERE tenant_id = #{tenantId}
AND quarter = #{quarter}
AND tag = 'red'
ORDER BY rank_points ASC
LIMIT #{limit}

SELECT 
FROM quarterly_snapshot
WHERE tenant_id = #{tenantId}
AND quarter = #{quarter}
AND tag = 'progress'
ORDER BY rank_progress ASC
LIMIT #{limit}

SELECT 
FROM quarterly_snapshot
WHERE tenant_id = #{tenantId}
AND quarter = #{quarter}
AND tag = 'warning'
ORDER BY quarter_net_points ASC

SELECT 
FROM quarterly_snapshot
WHERE tenant_id = #{tenantId}
AND quarter = #{quarter}
AND user_id = #{userId}

SELECT 
FROM quarterly_snapshot
WHERE tenant_id = #{tenantId}
AND quarter = #{quarter}
ORDER BY quarter_earned_points DESC, rule_count DESC,
activity_count DESC, no_penalty_days DESC, last_activity_time ASC

SELECT 
FROM quarterly_snapshot
WHERE tenant_id = #{tenantId}
AND quarter = #{quarter}
AND progress_points > 0
ORDER BY progress_points DESC

